"""
This script demonstrates how to interact with IPFS (InterPlanetary File System) using the `ipfshttpclient` library.
It retrieves content from IPFS by its address (CID - Content Identifier).
"""

import ipfshttpclient

def fetch_ipfs_content(cid):
    """
    Fetches content from IPFS using the provided CID (Content Identifier).

    Args:
        cid (str): The IPFS CID of the content to retrieve.

    Returns:
        str: The content retrieved from IPFS.

    Raises:
        ValueError: If the CID is invalid or empty.
        Exception: If there is an error connecting to the IPFS node or retrieving the content.
    """
    if not cid or not isinstance(cid, str):
        raise ValueError("Invalid CID provided. CID must be a non-empty string.")

    try:
        # Connect to the local IPFS node
        with ipfshttpclient.connect() as client:
            # Retrieve the content by CID
            content = client.cat(cid)
            return content.decode('utf-8')  # Decode bytes to string
    except ipfshttpclient.exceptions.ErrorResponse as e:
        raise Exception(f"Error retrieving content from IPFS: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

